function J({registerIndicator:x,sourceValues:w,nulls:A}){x({id:"oa-jvolty",name:"Jurik Volatility (JVOLTY)",category:"Volatility",placement:"pane",inputs:[{key:"period",type:"number",label:"Period",default:10,min:1,max:5e3,step:1,tooltip:"Number of bars used in the calculation."},{key:"source",type:"source",label:"Source",default:"close"}],plots:[{key:"jvolty",type:"line",title:"JVolty",style:{color:"#ffeb3b",lineWidth:2}}],calc(m,M){const l=Math.max(1,Math.floor(Number(M.period)||10)),n=w(m,M.source??"close"),i=m.length,p=new Array(i).fill(NaN),s=Math.max(Math.log(Math.sqrt(.5*(l-1)))/Math.log(2)+2,0),d=Math.max(s-2,.5),f=Math.sqrt(.5*(l-1))*s,L=2/(Math.max(4*l,65)+1),k=1/(10+10*Math.min(Math.max(l-10,0),100)/100),g=Math.pow(s,1/d),b=Number.isFinite(n[0])?n[0]:0;let N=b,v=b,c=0,a=0;const r=new Array(i).fill(NaN);for(let t=0;t<i;t++){const o=n[t];if(!Number.isFinite(o))continue;const u=o-N,h=o-v,y=Math.max(Math.abs(u),Math.abs(h));r[t]=y;const F=t>=10&&Number.isFinite(r[t-10])?r[t-10]:0;c=c+(y-F)*k,a=a+L*(c-a);let e=1;a>0&&(e=y/a,e=Math.min(Math.max(e,1),g));const V=Math.pow(f/(f+1),Math.sqrt(Math.pow(e,d)));N=u>0?o:o-V*u,v=h<0?o:o-V*h,Number.isFinite(e)&&(p[t]=e)}return{jvolty:A(p)}}})}export{J as default};
